// Safe way to run any script inside current package without the 
// problem of 'dev/prod' environment differencies: when package is installed as a dependency,
// 'dist/' always exists and has compiled scripts inside. But for a developer, 'dist' appears
// after install + build. Postinstall script that requires something to exist in dist/ makes 
// impossible to build this package in CI.

const fs = require('fs');
const { spawnSync } = require('child_process');
const path = require('path');

const packageDir = __dirname
const scriptName = process.argv[2]
const scriptPath = path.join(packageDir, scriptName)

if (fs.existsSync(scriptPath)) {
    spawnSync('node', [scriptPath, ...process.argv.slice(3)], { stdio: 'inherit' });
} else {
    console.log("Script '" + scriptName + "' is not found")
}